CREATE OR REPLACE PROCEDURE public.sp_update_teacher(IN p_id uuid, IN p_tenant_id uuid, IN p_person_id uuid, IN p_user_id uuid, IN p_employee_number character varying, IN p_first_name character varying, IN p_middle_name character varying, IN p_last_name character varying, IN p_preferred_name character varying, IN p_display_name character varying, IN p_profile_photo_url text, IN p_date_of_birth date, IN p_gender character varying, IN p_preferred_language character varying, IN p_other_languages text, IN p_pronouns character varying, IN p_bio text, IN p_status character varying, IN p_draft_data jsonb, IN p_profile_completion_percentage integer, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE teachers     SET person_id = p_person_id,         user_id = p_user_id,         employee_number = p_employee_number,         first_name = p_first_name,         middle_name = p_middle_name,         last_name = p_last_name,         preferred_name = p_preferred_name,         display_name = p_display_name,         profile_photo_url = p_profile_photo_url,         date_of_birth = p_date_of_birth,         gender = p_gender,         preferred_language = p_preferred_language,         other_languages = p_other_languages,         pronouns = p_pronouns,         bio = p_bio,         status = p_status,         draft_data = p_draft_data,         profile_completion_percentage = p_profile_completion_percentage,         updated_at = p_updated_at     WHERE id = p_id AND tenant_id = p_tenant_id; END; $procedure$ ;
